export const BODY: string = "\n<p>آپ کی GIF بھیجنے کے لیے بہت بڑی ہے۔ ڈسکارڈ اسے مسترد کر دیتا ہے، صفحہ آہستہ کھلتا ہے یا چیٹ ایپ اپ لوڈ کرنے سے انکار کر دیتی ہے۔</p>\n<p>GIF کمپریس کرنے میں تقریباً دو منٹ لگتے ہیں۔ آپ پیش سیٹ چنتے ہیں، پیلیٹ اور اسکیل بدلتے ہیں، حرکت کا پیش نظارہ دیکھتے ہیں اور چھوٹی فائل ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، ٹول کھولنے سے لے کر تیار GIF کو اس کی جگہ پر جانچنے تک۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو اصل GIF فائل چاہیے۔ چیٹ ایپ سے ڈاؤن لوڈ شدہ GIF پہلے سے کمپریس ہو سکتی ہے، اس لیے جب ممکن ہو ماخذ فائل استعمال کریں۔</p>\n<p>وہ سائز حد جان لیں جو آپ کو حاصل کرنی ہے۔ ڈسکارڈ، سلیک اور ویب سائٹس کی اپنی اپنی حدیں ہوتی ہیں، اور ہدف ہی ترتیبات طے کرتا ہے۔</p>\n<p>جان لیں کہ GIF کہاں دکھائی جائے گی۔ چھوٹا دکھایا جانے والا اسٹیکر بلاگ پوسٹ بھرنے والی GIF سے کم ڈیٹا مانگتا ہے۔ اصل فائل محفوظ رکھیں، اسے کمپریس شدہ کاپی سے کبھی اوور رائٹ نہ کریں۔</p>\n<h2 id=\"step-1-open\">مرحلہ 1: GIF کمپریسر کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/gif-compress-karein/\">GIF Compressor</a> کھولیں۔ اکاؤنٹ یا انسٹال کی ضرورت نہیں ہے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی حرکت مقامی طور پر پروسیس ہوتی ہے اور کبھی کسی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ ویسے ہی کام کرتا ہے۔ اپ لوڈ والے حصے پر ٹیپ کریں اور اپنی فائلوں سے GIF چنیں۔ اگر آپ اکثر GIF کمپریس کرتے ہیں تو صفحہ بک مارک کر لیں۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی GIF اپ لوڈ کریں</h2>\n<p>GIF کو اپ لوڈ والے حصے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ ٹول حرکت پڑھتا ہے، بشمول اس کے فریم، وقت اور لوپ ترتیبات۔</p>\n<p>GIF مکمل لوڈ ہونے کا انتظار کریں۔ بڑی فائلوں میں چند سیکنڈ لگتے ہیں، اور ٹول کو کام کرنے سے پہلے ہر فریم چاہیے ہوتا ہے۔</p>\n<p>صفحے پر دکھائی گئی اصل تفصیل جانچیں۔ کچھ بدلنے سے پہلے فائل سائز، ابعاد اور فریم گنتی نوٹ کریں۔ اگر GIF لوڈ نہ ہو تو فائل جانچیں۔</p>\n<h2 id=\"step-3-preset\">مرحلہ 3: پیش سیٹ چنیں</h2>\n<p>زیادہ تر GIF کے لیے Balanced چنیں۔ یہ پیلیٹ کم کرتا ہے، کچھ فریم کاٹتا ہے اور اچھے درمیانی نتیجے کے لیے سمجھداری سے اسکیل کرتا ہے۔</p>\n<p>جب GIF خوبصورت رہنی چاہیے تو Light چنیں۔ یہ پیلیٹ نرمی سے کاٹتا ہے اور حرکت ہموار رکھتا ہے۔</p>\n<p>جب فائل کو سخت حد میں فٹ ہونا ہو تو Max Shrink چنیں۔ یہ ہر لیور کو سخت دھکیلتا ہے اور سب سے چھوٹی فائل بناتا ہے۔ پیش سیٹ شروعاتی نقطہ طے کرتا ہے۔</p>\n<h2 id=\"step-4-adjust\">مرحلہ 4: پیلیٹ، اسکیل اور فریم بدلیں</h2>\n<p>مواد کے مطابق رنگ پیلیٹ طے کریں۔ تصویروں کے لیے 128 یا 256 رنگ استعمال کریں، اور فلیٹ گرافکس اور کارٹون کے لیے 64 یا 32 رنگ۔</p>\n<p>آؤٹ پٹ اسکیل دکھائی دینے والے سائز سے ملائیں۔ 400 پکسل چوڑی دکھائی دینے والی GIF کو فائل میں 1000 پکسل ہونے کی ضرورت نہیں ہے۔</p>\n<p>فریم ریٹ صرف اس وقت بدلیں جب GIF لمبی ہو۔ فریم گرانا اسکرین ریکارڈنگ اور آہستہ حرکت پر سب سے زیادہ مدد کرتا ہے۔ ایک وقت میں ایک ترتیب بدلیں۔</p>\n<h2 id=\"step-5-run\">مرحلہ 5: کمپریشن چلائیں</h2>\n<p>کمپریشن شروع کریں اور پیش رفت دیکھیں۔ ٹول فریم پروسیس کرتا ہے اور چھوٹی GIF بناتا ہے۔</p>\n<p>بڑی GIF چھوٹی سے زیادہ وقت لیتی ہے۔ 20 MB کلپ کو 2 MB ری ایکشن سے زیادہ پروسیسنگ وقت چاہیے ہوتا ہے۔</p>\n<p>ٹول چلتے ہوئے ٹیب بند نہ کریں۔ کام آپ کے براؤزر میں ہوتا ہے، اور صفحہ بند کرنے سے کمپریشن رک جاتی ہے۔ مکمل ہونے پر ٹول نیا فائل سائز اور بچت کا فیصد دکھاتا ہے۔</p>\n<h2 id=\"step-6-preview\">مرحلہ 6: حرکت کا پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ GIF کا پیش نظارہ دیکھیں۔ اسے کم از کم ایک مکمل لوپ چلتا ہوا دیکھیں۔</p>\n<p>پہلے وقت جانچیں۔ حرکت اصل جیسی رفتار پر چلنی چاہیے، نہ تیز اور نہ سست۔ پھر رنگ جانچیں۔ چھوٹے پیلیٹ پر تصویری GIF میں بینڈنگ آ سکتی ہے، جبکہ گرافکس صاف رہنے چاہییں۔</p>\n<p>آخر میں ہمواری جانچیں۔ گرائے گئے فریم تیز حرکت کو جھٹکے دار بنا سکتے ہیں، جبکہ آہستہ حرکت ہموار رہتی ہے۔ اگر سائیڈ بائی سائیڈ منظر دستیاب ہو تو اسے استعمال کریں۔</p>\n<h2 id=\"step-7-download\">مرحلہ 7: ڈاؤن لوڈ کریں اور آزمائیں</h2>\n<p>کمپریس شدہ GIF ڈاؤن لوڈ کریں۔ اس کا نام اسے کمپریس شدہ نسخہ کے طور پر ظاہر کرے گا۔</p>\n<p>اپنے آلے پر فائل سائز جانچیں۔ یقین کریں کہ یہ اس پلیٹفارم کی حد میں آتی ہے جہاں اسے استعمال ہونا ہے۔</p>\n<p>GIF کو وہیں آزمائیں جہاں وہ رہے گی۔ اسے ڈسکارڈ پر خود کو بھیجیں، یا وہ صفحہ کھولیں جہاں وہ دکھائی دے گی، اور اسے چلتا ہوا دیکھیں۔ اصل فائل محفوظ رکھیں۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر GIF اب بھی فٹ نہ ہو تو اسکیل مزید کم کریں۔ ابعاد آدھے کرنے سے فائل سائز ڈرامائی طور پر کم ہو جاتا ہے۔</p>\n<p>اگر رنگ غلط لگیں تو پیلیٹ بڑھائیں۔ 32 رنگ پر تصویری GIF بری طرح بینڈ کرے گی، جبکہ 128 رنگ اسے ٹھیک کر دیتے ہیں۔</p>\n<p>اگر حرکت جھٹکے دار چلے تو کچھ گرائے گئے فریم واپس لائیں۔ تیز حرکت کو ہموار دکھنے کے لیے زیادہ فریم چاہییں۔ اگر فائل چھوٹی ہونے کی بجائے بڑی ہو گئی تو اصل پہلے سے چھوٹی تھی۔</p>\n<h2 id=\"discord-workflow\">ورک فلو: ڈسکارڈ کے لیے GIF</h2>\n<p>اپنے اکاؤنٹ کے لیے ڈسکارڈ کی حد جانچیں۔ مفت اکاؤنٹ اپ لوڈ 8 MB تک محدود کرتے ہیں، اور ہدف آپ کی ترتیبات طے کرتا ہے۔</p>\n<p>GIF کمپریسر پر اپ لوڈ کریں اور اگر فائل حد سے بہت اوپر ہو تو Max Shrink چنیں۔ صرف تھوڑی اوپر ہو تو Balanced کام کرتا ہے۔</p>\n<p>حرکت کو احتیاط سے پیش نظارہ دیکھیں۔ ری ایکشن GIF چھوٹی ہوتی ہیں، اس لیے ایک لوپ میں کوئی بھی نقصان آسانی سے نظر آ جاتا ہے۔</p>\n<h2 id=\"website-workflow\">ورک فلو: ویب سائٹ کے لیے GIF</h2>\n<p>صفحے پر GIF کا کردار ناپیں۔ چھوٹے سجاوٹی لوپ کو مکمل چوڑائی والے مظاہرے سے کہیں کم ڈیٹا چاہیے ہوتا ہے۔</p>\n<p>GIF اپ لوڈ کریں اور Balanced چنیں۔ اسے دکھائی دینے والی چوڑائی پر اسکیل کریں تاکہ فائل میں ضائع شدہ پکسل نہ ہوں۔</p>\n<p>حرکت کو اسی سائز پر پیش نظارہ دیکھیں جس پر وہ دکھائی دے گی۔ بڑی اچھی لگنے والی GIF چھوٹی کھردری لگ سکتی ہے، اور اس کے الٹ بھی۔</p>\n<h2 id=\"phone-workflow\">ورک فلو: اپنے فون پر</h2>\n<p>موبائل براؤزر میں ٹول کھولیں اور اپ لوڈ والے حصے پر ٹیپ کریں۔ اپنی فائلوں سے GIF چنیں۔</p>\n<p>پیش سیٹ چنیں اور اسکیل اس جگہ سے ملائیں جہاں GIF دکھائی جائے گی۔ چھوٹی اسکرینوں کو چھوٹی فائلیں چاہییں۔</p>\n<p>فون کی اسکرین پر حرکت کا پیش نظارہ دیکھیں۔ ڈاؤن لوڈ سے پہلے مکمل لوپ دیکھیں۔ ڈاؤن لوڈ شدہ فائل Files ایپ میں تلاش کریں اور سائز یقینی کریں۔</p>\n<h2 id=\"gif-sizes-by-platform\">پلیٹفارم کے حساب سے سائز حدیں</h2>\n<p>ہر پلیٹفارم GIF اپ لوڈ کی حد مختلف رکھتا ہے۔ کمپریس کرنے سے پہلے حد جاننا مسترد شدہ اپ لوڈ سے بچاتا ہے۔</p>\n<p>ڈسکارڈ مفت اکاؤنٹ کے لیے 8 MB اور ادا شدہ کے لیے زیادہ دیتا ہے۔ حد سے تھوڑی اوپر GIF کو فٹ ہونے کے لیے صرف ہلکی کمی چاہیے ہوتی ہے۔</p>\n<p>سلیک فائلوں کے لیے 1 GB تک اپ لوڈ دیتا ہے، مگر چند میگا بائٹ سے بڑی GIF چیٹ ونڈو میں خراب چلتی ہے۔ حد فراخ ہو تب بھی چھوٹی بہتر ہے۔</p>\n<h2 id=\"trimming-gifs\">کمپریس کرنے سے پہلے GIF تراشنا</h2>\n<p>سب سے مؤثر کمپریشن مواد ہٹانا ہے۔ دس سیکنڈ سے پانچ سیکنڈ تک تراشی گئی GIF فوراً آدھے فریم کھو دیتی ہے۔</p>\n<p>بورنگ شروعات اور اختتام کاٹ دیں۔ زیادہ تر کلپ میں ایک سیکنڈ کی تیاری اور ایک سیکنڈ کا اختتام ہوتا ہے جو کچھ نہیں جوڑتا۔</p>\n<p>بہترین لوپ نقطہ رکھیں۔ بغیر جھٹکے لوپ ہونے والی GIF لمبی محسوس ہوتی ہے، جبکہ نظر آنے والی چھلانگ والی GIF ٹوٹی محسوس ہوتی ہے۔</p>\n<h2 id=\"preview-tips\">پیش نظارہ کے نکات جو مسائل پکڑتے ہیں</h2>\n<p>کمپریس شدہ GIF کا پیش نظارہ اسی آلے پر دیکھیں جہاں وہ دکھائی جائے گی۔ لیپ ٹاپ پر ٹھیک لگنے والی GIF فون پر کھردری لگ سکتی ہے۔</p>\n<p>کم از کم تین مکمل لوپ دیکھیں۔ کچھ مسائل، جیسے لوپ نقطے پر رکاوٹ، پہلی بار چلنے کے بعد ہی ظاہر ہوتے ہیں۔</p>\n<p>GIF کو گہرے پس منظر اور ہلکے پس منظر دونوں پر جانچیں۔ سفید پر ٹھیک لگنے والے شفاف کنارے گہرے پر ہالہ دکھا سکتے ہیں۔</p>\n<h2 id=\"gif-batch\">ایک ساتھ کئی GIF کمپریس کرنا</h2>\n<p>GIF کمپریسر ایک وقت میں ایک حرکت سنبھالتا ہے۔ GIF کے سیٹ کے لیے انہیں ایک ایک کر کے اسی پیش سیٹ کے ساتھ کمپریس کریں۔</p>\n<p>پورے سیٹ میں ترتیبات مستقل رکھیں۔ ملے جلے پیلیٹ اور اسکیل والا ری ایکشن پیک ساتھ شیئر ہونے پر بے ترتیب لگتا ہے۔</p>\n<p>پہلی GIF پر کام کرنے والی ترتیبات نوٹ کریں۔ انہیں باقی پر دوبارہ استعمال کرنے سے سیٹ یکساں رہتا ہے، بغیر ہر بار دوبارہ فیصلہ کیے۔</p>\n<h2 id=\"gif-quality-scale\">GIF کوالٹی پرکھنا: کیا دیکھیں</h2>\n<p>کمپریس شدہ GIF کو تین چیزوں سے پرکھیں: ہمواری، رنگ اور نفاست۔ ہر ایک اپنے انداز میں ناکام ہوتی ہے، اور ہر ایک کا اپنا حل ہے۔</p>\n<p>ہمواری اس وقت ناکام ہوتی ہے جب فریم بہت جارحانہ انداز میں گرائے جائیں۔ تیز حرکت جھٹکے دار ہو جاتی ہے، اور حل فریم واپس لانا ہے۔</p>\n<p>رنگ اس وقت ناکام ہوتا ہے جب پیلیٹ بہت چھوٹا ہو۔ جلد بینڈ کرتی ہے، آسمان دھاری دار ہوتا ہے، اور حل بڑا پیلیٹ ہے۔</p>\n<h2 id=\"when-gif-fails\">جب GIF بچائی نہ جا سکے</h2>\n<p>کچھ GIF اتنی کمپریس نہیں ہو سکتیں۔ لمبی، تفصیلی، تصویری کلپ Max Shrink پر بھی حد سے اوپر رہ سکتی ہے۔</p>\n<p>اس صورت میں فارمیٹ بدلیں۔ MP4 یا متحرک WebP میں بدلنا فائل کو کسی بھی GIF ترتیب سے کہیں زیادہ چھوٹا کر دیتا ہے۔</p>\n<p>یا مواد بدلیں۔ کلپ تراشنا، فریم کراپ کرنا یا فریم ریٹ کم کرنا ناممکن GIF کو پہنچ میں لا سکتا ہے۔ یا حد قبول کریں۔</p>\n<h2 id=\"gif-future\">ویب پر GIF کا مستقبل</h2>\n<p>GIF پرانی ہے، مگر یہ جا نہیں رہی۔ اس کی عالمگیر چلنے کی صلاحیت اسے چیٹ، ای میل اور سوشل میڈیا میں زندہ رکھتی ہے۔</p>\n<p>ویب سائٹس لمبی حرکت کے لیے ویڈیو کی طرف جا رہی ہیں۔ آٹو پلے والا MP4 دسویں حصے کے وزن پر GIF جیسا برتاؤ کرتا ہے، اور یہ تبدیلی پہلے سے ہو رہی ہے۔</p>\n<p>متحرک WebP درمیانی راستے کے طور پر بڑھ رہا ہے۔ یہ بہتر کمپریشن کے ساتھ آسان چلنا برقرار رکھتا ہے، اور براؤزر سپورٹ اب وسیع ہے۔</p>\n<h2 id=\"keep-practising-gif\">اصل GIF کے ساتھ مشق جاری رکھیں</h2>\n<p>ہر GIF جو آپ کمپریس کرتے ہیں، کچھ سکھاتی ہے۔ نوٹ کریں کہ کون سا پیش سیٹ کام آیا، کون سا اسکیل دکھائی دینے والے سائز کو سوٹ کیا اور فائل سائز نے کیا کیا۔</p>\n<p>یہ نوٹ آپ کی پلے بک بن جاتے ہیں۔ اگلی GIF کم وقت لیتی ہے، کیونکہ پچھلی نے سوالات کے جواب پہلے دے دیے تھے۔</p>\n<p>GIF کمپریشن کی مکمل رہنما کے لیے <a href=\"/ur/blog/gif-compressor-rehnumai/\">GIF Compressor: Complete Guide</a> پڑھیں۔ فارمیٹ موازنے کے لیے <a href=\"/ur/blog/gif-vs-webp-vs-mp4-animated-muqabla/\">GIF vs WebP vs MP4: Animated Images Compared</a> دیکھیں۔ اگر آپ تصویروں سے GIF بناتے ہیں تو <a href=\"/ur/gif-maker/\">GIF Maker</a> انہیں پہلے بناتا ہے۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ڈسکارڈ کے لیے GIF کیسے کمپریس کروں؟","answer":"GIF کمپریسر کھولیں، GIF اپ لوڈ کریں اور اگر وہ 8 MB مفت حد سے بہت اوپر ہو تو Max Shrink چنیں۔ اسکیل دکھائی دینے والے سائز سے ملائیں اور حرکت کا پیش نظارہ دیکھیں۔ فائل ڈاؤن لوڈ کریں، حد میں آنا یقینی کریں اور پہلے خود کو بھیج کر تصدیق کریں کہ وہ ٹھیک چلتی ہے۔"},{"question":"کمپریشن کے بعد میری GIF جھٹکے دار کیوں لگتی ہے؟","answer":"بہت زیادہ فریم گرائے گئے تھے۔ فریم گرانے سے کل مدت رہتی ہے مگر درمیانی فریم ہٹ جاتے ہیں، جس سے تیز حرکت جھٹکے دار لگتی ہے۔ کم فریم گرانے یا نرم پیش سیٹ کے ساتھ دوبارہ آزمائیں، اور ڈاؤن لوڈ سے پہلے مکمل لوپ کا پیش نظارہ دیکھیں۔"},{"question":"کیا GIF کوالٹی کھوئے بغیر کمپریس کر سکتا ہوں؟","answer":"کچھ نقصان ناگزیر ہے، کیونکہ GIF کمپریشن رنگ، فریم یا پکسل ہٹاتی ہے۔ مگر مناسب پیلیٹ کے ساتھ Balanced پیش سیٹ پر محتاط کمپریشن سے نقصان تقریباً نظر نہیں آتا۔ اصل فائل سے شروع کریں، پہلے سے کمپریس شدہ کاپی سے نہیں۔"},{"question":"اسکرین ریکارڈنگ GIF کے لیے بہترین پیلیٹ سائز کیا ہے؟","answer":"اسکرین ریکارڈنگ میں فلیٹ رنگ اور تیز متن ہوتے ہیں، اس لیے 64 رنگ عام طور پر اچھا کام کرتے ہیں۔ پہلے 128 آزمائیں اور اگر فائل اب بھی بہت بڑی ہو تو 64 پر جائیں۔ دونوں سائز پر متن پڑھنے کے قابل رہتا ہے، جو ریکارڈنگ کے لیے اہم ہے۔"},{"question":"GIF کتنی چھوٹی ہو سکتی ہے؟","answer":"یہ لمبائی، ابعاد اور مواد پر منحصر ہے۔ چھوٹی ری ایکشن GIF 1 MB سے نیچے جا سکتی ہے، جبکہ دس سیکنڈ کی کلپ Max Shrink پر بھی 5 MB سے اوپر رہ سکتی ہے۔ بہت لمبی کلپ کے لیے MP4 یا WebP ویڈیو GIF سے بہتر فارمیٹ ہے۔"},{"question":"کیا GIF کمپریس کرنے سے اس کی شفافیت ختم ہو جاتی ہے؟","answer":"نہیں، کمپریشن کے دوران شفافیت محفوظ رہتی ہے۔ شفاف حصے کمپریس شدہ فائل میں شفاف رہتے ہیں۔ پیلیٹ بہت کم کرنے سے نرم شفاف کنارے کھردرے ہو سکتے ہیں، اس لیے اسٹیکر اور اوورلے کے لیے پیلیٹ فراخ رکھیں۔"}];
